pipeline {
    agent any

    options {
        timeout(time: 1, unit: 'HOURS')
        timestamps()
        disableConcurrentBuilds()
    }

    stages {
        stage('Build') {
            steps {
                echo "[Build] Compiling source code..."
            }
        }
        stage('Test') {
            steps {
                echo "[Test] Running automated test suites..."
            }
        }
    }
}

node('linux-agent') {
    stage('Prepare') {
        def appVersion = "1.0.0"
        println "Building version: ${appVersion}"
    }
    stage('Execute') {
        try {
            sh 'echo Running scripted pipeline step'
        } catch (Exception err) {
            println "Caught error: ${err.message}"
            currentBuild.result = 'FAILURE'
        }
    }
}

pipeline {
    agent any

    parameters {
        choice(name: 'ENVIRONMENT', choices: ['dev', 'staging', 'prod'], description: 'Deployment Target')
        booleanParam(name: 'RUN_INTEGRATION_TESTS', defaultValue: true, description: 'Run extended test suite')
    }

    environment {
        APP_NAME = 'trak-api'
        BUILD_VERSION = "${env.BUILD_NUMBER}"
    }

    stages {
        stage('Deploy') {
            steps {
                echo "Deploying ${env.APP_NAME} (Build #${env.BUILD_VERSION}) to target: ${params.ENVIRONMENT}"
            }
        }
    }
}

pipeline {
    agent any
    stages {
        stage('Publish Artifacts') {
            steps {
                withCredentials([usernamePassword(credentialsId: 'nexus-credentials', usernameVariable: 'NEXUS_USER', passwordVariable: 'NEXUS_PASS')]) {
                    sh 'echo Authenticating as user: $NEXUS_USER'
                    // Passwords are automatically masked in build logs as ****
                }
            }
        }
    }
}

pipeline {
    agent {
        docker {
            image 'node:20-alpine'
            args '-v /tmp/cache:/root/.npm'
        }
    }
    stages {
        stage('Build & Test in Container') {
            steps {
                sh 'node --version'
                sh 'npm --version'
            }
        }
    }
}

pipeline {
    agent any
    stages {
        stage('Checkout') {
            steps {
                checkout scm
                echo "Current Git Branch: ${env.BRANCH_NAME}"
            }
        }
    }
}

pipeline {
    agent any
    stages {
        stage('Parallel Test Suites') {
            parallel {
                stage('Unit Tests') {
                    steps { echo 'Running unit tests in parallel...' }
                }
                stage('Lint & Static Analysis') {
                    steps { echo 'Running ESLint / SonarQube...' }
                }
                stage('Security Scan') {
                    steps { echo 'Running Trivy container scan...' }
                }
            }
        }
    }
}

pipeline {
    agent any
    stages {
        stage('Deploy to Production') {
            when {
                branch 'main'
                tag 'v*'
            }
            steps {
                echo 'Deploying release tag to production...'
            }
        }
    }
}

pipeline {
    agent any
    stages {
        stage('Test') {
            steps {
                echo 'Testing...'
            }
        }
    }
    post {
        always {
            cleanWs() // Clean workspace
        }
        success {
            echo 'Pipeline completed successfully!'
        }
        failure {
            echo 'Pipeline failed! Sending alert notification.'
        }
    }
}

