pipeline {
    agent any
    stages {
        stage('Shared Step Call') {
            steps {
                // standardBuildPipeline(appName: 'orders-service', notifySlack: true)
                echo 'Executing shared library custom step'
            }
        }
    }
}

pipeline {
    agent any
    stages {
        stage('Build') {
            steps {
                sh 'echo "Compiled App binary" > app.bin'
                archiveArtifacts artifacts: '*.bin', fingerprint: true
            }
        }
    }
}

pipeline {
    agent any
    stages {
        stage('Production Approval Gate') {
            steps {
                timeout(time: 1, unit: 'DAYS') {
                    input message: 'Do you approve deploying to Production?', submitter: 'admin,lead-dev'
                }
            }
        }
        stage('Deploy') {
            steps {
                echo 'Deploying to Production cluster...'
            }
        }
    }
}

pipeline {
    agent {
        kubernetes {
            yaml '''
apiVersion: v1
kind: Pod
spec:
  containers:
  - name: maven
    image: maven:3.9-eclipse-temurin-17
    command: ['sleep']
    args: ['99d']
'''
        }
    }
    stages {
        stage('Build in Kubernetes Pod') {
            steps {
                container('maven') {
                    sh 'mvn --version'
                }
            }
        }
    }
}
